#!/usr/bin/env python3
"""Generate factual acceptance evidence from preserved stage5 raw results."""
import argparse,csv,hashlib,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--release-dir',type=Path);args=p.parse_args();root=args.root.resolve();team=root/'src/team_04';out=team/'artifacts/stage5';release=args.release_dir.resolve() if args.release_dir else out/'final_release'
def read(p,default=None):return json.loads(p.read_text()) if p.is_file() else default
def f(v):return '미계측' if v is None else f'{v:.3f}' if isinstance(v,(int,float)) else str(v)
rows=[];raw={}
for folder in sorted(out.glob('stage5-*')):
 r=read(folder/'result.json');m=read(folder/'metrics.json',{})
 if r is None or 'track' not in r or r.get('error'):continue
 raw[folder.name]=(r,m)
 row=dict(trial=folder.name,track=r['track'],scenario=r.get('scenario'),traffic_mode=r.get('traffic_mode'),termination=r.get('termination') or 'duration',distance_m=r.get('distance_m'),sim_s=r.get('sim_duration'),wall_s=r.get('wall_duration'),contacts=len(r.get('contacts',[])),offroad_frames=m.get('offline_offroad_frames'),minimum_gap_m=m.get('minimum_full_footprint_gap_m'),attempts=m.get('overtake_attempts'),completed=m.get('overtake_completions'),aborts=m.get('overtake_aborts'),strict_pass=m.get('strict_overtake_success'),active_stops=m.get('active_safety_stops'),raw_stop_counter=m.get('raw_stop_counter'),recall=m.get('range_qualified_detection_recall'),false_fraction=m.get('detection_false_fraction'),id_retention=m.get('track_id_retention'),range_error_m=m.get('range_error_to_nearest_physical_footprint_m'),closing_error_mps=m.get('closing_speed_absolute_error_mps'),ttc_error_s=m.get('constant_velocity_ttc_absolute_error_s'),hazard_latency_s=m.get('collision_risk_detection_latency_s'),actual_average_speed_mps=m.get('actual_average_pose_speed_mps'),steering_rate_p95=m.get('steering_rate_p95_rad_s'),max_steering_delta_rad=m.get('steering_delta_max_rad'),observed_steering_rate_max=m.get('observed_command_steering_rate_max_rad_s'),maximum_simultaneous_tracks=m.get('maximum_simultaneous_tracks'),maximum_track_missed_s=m.get('maximum_track_missed_s'),over50ms_records=m.get('traffic_processing_over50ms_records'),front_steering_max_deg=m.get('actual_front_steering_max_deg'),lidar_hz=m.get('active_sensor_hz'),processing_ms=m.get('traffic_processing_ms'),sensor_age_s=m.get('sensor_age_s'),cpu_one_core_mean=m.get('cpu_percent_one_core_mean'),rss_sum_mb=m.get('process_rss_sum_mb'),rtf=m.get('active_rtf'),lap_times_s=r.get('lap_times_seconds'),runtime_fingerprints=read(folder/'run_config.json',{}).get('runtime_fingerprints'))
 rows.append(row)
(out/'scenario_matrix.json').write_text(json.dumps(rows,indent=2)+'\n')
if rows:
 with (out/'scenario_matrix.csv').open('w') as stream:
  w=csv.DictWriter(stream,fieldnames=list(rows[0]));w.writeheader();w.writerows({k:json.dumps(v) if isinstance(v,(dict,list)) else v for k,v in row.items()} for row in rows)
solo=[(n,r,m) for n,(r,m) in raw.items() if r.get('scenario')=='solo'];solo_name,solo_result,solo_metrics=solo[-1] if solo else ('미실행',{},{});check=read(release/'relocation_check.json',{});safety=read(release/'ros_safety.json',{});audit=read(out/'preservation_audit.json',{})
passes=[row['trial'] for row in rows if row['strict_pass']];both_directions=all(any(row['strict_pass'] and row['scenario'].startswith(side) for row in rows) for side in ['left','right']);contacts=sum(row['contacts'] for row in rows);gaps=[row['minimum_gap_m'] for row in rows if row['minimum_gap_m'] is not None]
cpp=(release/'ctest.log').read_text() if (release/'ctest.log').exists() else ''
accept=dict(status='complete' if both_directions and not contacts and all(row['offroad_frames']==0 for row in rows) and '100% tests passed' in cpp and check and len(safety)==14 and all(safety.values()) and solo_metrics.get('self_two_lap_under_600wall') else 'partial_acceptance',physical_strict_pass_trials=passes,both_directions_passed=both_directions,physical_completed_trials=len(rows),infrastructure_failure_trials=['stage5-s01-stopped'],operator_interrupted_trials=[p.parent.name for p in out.glob('stage5-*/interruption.json')],vehicle_and_wall_contact_records=contacts,minimum_observed_full_footprint_gap_m=min(gaps) if gaps else None,cpp_three_executables_passed='100% tests passed' in cpp,ros_safety14_passed=len(safety)==14 and all(safety.values()),fresh_release_check=check,solo_trial=solo_name,solo_two_lap_under600wall=solo_metrics.get('self_two_lap_under_600wall',False),old_records_protected=audit.get('old_records_and_protected_unchanged',False),official_lap_certified=False,limitations=['native S01 abort is not a driving result','physical front camera masks shallow forward LiDAR rays','safe abort is not a completed pass','full traffic laps and twelve full-sensor vehicles unexecuted'])
(out/'acceptance.json').write_text(json.dumps(accept,indent=2)+'\n')
sections=[]
def section(title,text):sections.append(f'## {len(sections)+1}. {title}\n\n{text}\n')
section('기존 4단계 성능','Monza 상한4.5m/s, 연속3랩 무접촉. 기존 첫2랩591.728wall초, 신호 절차 포함599.631wall초. Hungaroring 상한2.5m/s355.520sim초. 기존 결과와 ZIP은 변경하지 않았고 stage5에 동결 사본을 보존했다.')
section('수정 및 신규 생성 파일','기존 autonomy/후보 계획기/관측 경계에 선택적 교통 훅을 추가했다. 신규 traffic.hpp, lidar_motion.cpp, vehicle_detector.cpp, vehicle_tracker.cpp, collision_predictor.cpp, overtake_planner.cpp가 인식·추적·예측·상태 전이를 담당한다. 새 fixture/actor/trial/campaign/analyzer/단위시험/시각화/문서/설정은 team04_race 내부다. 변경 파일 전체 목록은 preservation_audit.json의 changed_source_files, 신규 파일은 baseline.json과 최종 ZIP 목록을 비교한다. 버전0.5.0, 공식 기본값은 solo_racing/4.5m/s다.')
section('보호 파일 무변경 검증',f"기준5102개 파일 감사: {audit.get('old_records_and_protected_unchanged',False)}. 차량·센서·control/scan/vehicle_system 무변경: {audit.get('unchanged_vehicle_sensor_and_control',False)}. 기존 기록·공식 track/world/race/경기 스크립트와 stage4 ZIP 보존. SHA256: `{audit.get('stage4_zip_sha256','미검사')}`. 실제 상대 시험 모델도 sensor/plugin을 제외한 링크·관성·collision·joint 구조가 원본과 동일함을 canonical XML로 검사했다.")
section('LiDAR 차량 탐지 알고리즘','자기16×720 PointCloud2의 기존 노면 평면과 높이0.035~0.38m 장애물을 재사용한다. 0.12m 그리드에서0.17m 거리 연결, 최소3점·XY폭0.02m 조건으로 후보를 추출한다. 관측 길이/폭, bbox, 거리, 방위각, 신뢰도, timestamp, 내부 여부, 위치 불확실성을 보존한다. 실제 min-X/median-Y 반사면이 추적 기준이며 완전한 차량 중심으로 간주하지 않는다. 작은 housing 점군은 차량 확정 대신 불확실 점유다.')
section('차량과 방호벽 구분','현재 좌우 관측 단면과 현재 실제 벽 반사점 적합으로 경계 조각을 분리한다. 분류는 실제 연속 단면이 이루는 polygon 안에 있어야 하며 먼 전방/곡선 끝의 단면을 연장하지 않는다. 원점±0.8m의 front/rear 단면 사이 측방 구간은 현재 실제 직선벽 적합이 충분한 경우에만 내부를 분류한다. 이 보완은 분류 전용이며 경로나 벽 반사점을 생성하지 않는다. Q01에서 첫 코너 벽 끝점을 차량으로 오인해 단독 회귀가 실패했고, 해당 실패 raw cloud에서 수정 후 탐지0을 확인했다. 이전 벽 모델은 현재 raw 반사점 연결 힌트로만 사용하며 경계·점군·진행 경로를 합성하지 않는다. 차량 반사점 제거는 경계 추출에만 적용하고 최종 원본 raw 장애물 검사는 모두 복원한다. 곡선/희소 벽에서는 보정이 제한된다. L06의 벽 조각 오탐을 계기로 이 처리를 보강했다.')
section('다중 차량 추적','일대일 gated 최근접 연결+alpha-beta 필터, 최대16ID. 연결 순서 변경·가림·만료 시험을 포함한다.1초 이상 미관측 ID는 만료하되 미확인 점유는 별도 유지한다. 실제 광선이 기존 위치를 통과해야 앞쪽 점유를 해제한다. 추적/유령 점유 용량 초과는 정지 fault를 고정한다. 후방 판정도 자기360도 raw LiDAR를 반전하여 현재 실제 경계를 확인한다.')
section('상대속도 추정','거리 변화와 직전 명령의 SE(2) 좌표변환으로 접근속도와 상대차 속도를 추정한다. 엄격한 직선 벽 적합에서만 yaw/횡변위를0.1 가중치로 보정한다. 평행 벽의 전진 변위는 관측 불가능하며 명령 모델을 사용한다. 센서 반사면 변화와 조향 응답 지연 때문에 횡속도 편향이 남아 있다. IMU/encoder/pose는 제어에 연결하지 않았다.')
section('TTC 계산 및 한계','TTC=max(0,팽창 종방향 간격)/보수적 접근속도. 접근하지 않으면 무한대, 신규/소실 객체에는 자차 명령속도를 추가한다. 반응시간+명령 제동시간 이하이면 긴급 제동한다. 모든 상대 반사면에0.64m 등방성 hidden-body 여유+관측 크기+불확실성을 적용해 가려진 차체를 축소하지 않는다. 후보 전체 자세에 회전 자차 사각형과 상대 미래 AABB의 SAT 검사를 적용한다. TTC 오차는 독립 pose의 일정속도 참고값 대비이며 실제 미래 충돌 시각 보장이 아니다.')
section('추월 상태 머신','RACING → TARGET_DETECTED/FOLLOWING/OVERTAKE_PLANNING → OVERTAKE_LEFT/RIGHT → SIDE_BY_SIDE → RETURN_TO_RACING_LINE → RACING. 위험하면 ABORT_OVERTAKE/EMERGENCY_BRAKING. 방향 고정·권한 후0.8초 관측·5hits·현재6점·곡률/거리 조건을 적용한다. 추월 후보는 최대4m 실제 관측 구간에서 매 스캔 재계획하며 기존 제동거리와 lookahead 조건도 만족해야 한다. 단독 계획은 기존10m다. 상대 전체 앞쪽이 자차 뒤로 관측되고 같은 ID가 전면에서 후면으로 넘어간 것이 확인되어야 복귀한다. 짧은 측방 센서 공백을 건너 같은 ID가 뒤에서 관측된 경우도 crossing으로 인정하지만, 미관측/다른 ID는 복귀를 허용하지 않는다. 포기 후 완료 횟수를 올리지 않는다.')
def table(selected):
 s='|시험|트랙|거리m|sim초|wall초|최소간격m|접촉|시도/완료/포기|주행정지|판정|\n|---|---|---:|---:|---:|---:|---:|---|---:|---|\n'
 for r in selected:s+=f"|{r['trial']}|{r['track']}|{f(r['distance_m'])}|{f(r['sim_s'])}|{f(r['wall_s'])}|{f(r['minimum_gap_m'])}|{r['contacts']}|{r['attempts']}/{r['completed']}/{r['aborts']}|{r['active_stops']}|{'추월 완료' if r['strict_pass'] else '접촉/이탈' if r['contacts'] or r['offroad_frames'] else '미완료·추종/정지/포기'}|\n"
 return s
section('좌측 추월 결과',table([r for r in rows if (r['scenario'] or '').startswith('left')])+'\n단위시험의 후보 생성 통과와 실제 추월 완료는 별개다. 포기·단순 전진은 성공으로 세지 않았다.')
section('우측 추월 결과',table([r for r in rows if (r['scenario'] or '').startswith('right')]))
section('추월 실패 및 포기 사례','S01: 시험 도구가 ROS Vector3에 정수0을 넣어 native abort. 불완전 계측이므로 접촉0/성공으로 세지 않았다. 해당 GZ partition만 종료하고 변환을 수정했다. L01~L09/H01~H02: 횡속도 편향·미래 점유와 후보 충돌, 벽 조각 오탐, 소실 점유로 포기했다. 원본 실패 로그는 모두 보존했다. 후속4m 국소 계획은 먼 미래 예측 문제를 줄이지만 안전 검사를 제거하지 않는다. 양측 충분한 공간이 없거나 관측 신뢰가 부족하면 정지한다.')
section('코너 추월 시험',table([r for r in rows if r['scenario']=='corner'])+'\n검증한 구간에 한정한 결과이며 전체 코너 및 임의 상대 행동을 보장하지 않는다.')
section('다중 차량 시험',table([r for r in rows if r['scenario'] in ['multi','blocked','occlusion','cutin']])+'\n동시에2~3개 물리 actor를 사용했다. 생성 actor 수와 실제 매 프레임 탐지 수를 구분하며 세부 ID·recall은 scenario_matrix.json/각 traffic.json에 있다.12팀 동시 센서 부하는 미실행.')
section('최소 차간 거리',f"완료된 교통 시험의 최소 관측 전체 외형 간격: {f(min(gaps) if gaps else None)}m. 독립 ego/actor pose에0.520×0.238958m 회전 사각형을 적용했다. 샘플 사이 보간값이며 실제 접촉 판정은 매 물리 step contact observer를 별도로 사용한다. 거리와 인식/속도/TTC 오차의 표본 수·평균/p95/최대는 scenario_matrix.json과 각 metrics.json 참조. 가림을 포함한10m 이내 recall이므로 완전한 visibility 정답은 아니다.")
section('접촉 횟수',f"정상 종료한 {len(rows)}회 실제 시험의 차량/벽 접촉 레코드 합계 {contacts}. actor와 자차의 노면 정상 접촉은 충돌로 세지 않는다. S01의 계측 미완료는 이 집계에서 제외한다. 접촉 observer 수신 여부도 별도 검사한다. 이 숫자를 미래 모든 상황의 무접촉 보장으로 해석하지 않는다.")
section('안전 정지 횟수','각 시험의 active_stops와 raw_stop_counter를 scenario_matrix.json에 저장했다. 원시 카운터에서 대기 중 timeout을 지우지 않으며 출발 후 fault와 구분한다. 소실 점유/제동 경로 부족/미래 충돌로 인한 정지는 안전 대응이며 추월 성공이 아니다. 정지차·급제동·추종 결과:\n\n'+table([r for r in rows if r['scenario'] in ['stopped','follow','follow_offset','brake']]))
section('Monza 단독 성능 회귀',f"시험 `{solo_name}`. {len(solo_result.get('lap_records',[]))}랩, 랩별sim시간 {solo_result.get('lap_times_seconds',[])}. arm부터2랩wall {f(solo_metrics.get('first_two_laps_wall_from_arm_s'))}초, 신호 포함 보수적wall {f(solo_metrics.get('first_two_laps_wall_including_lights_conservative_s'))}초, release부터2랩sim {f(solo_metrics.get('first_two_laps_sim_from_release_s'))}초. 접촉 {solo_metrics.get('contacts','미실행')}, 주행 안전 정지 {solo_metrics.get('active_safety_stops','미실행')}.600wall 기준 충족: {solo_metrics.get('self_two_lap_under_600wall',False)}.4.5m/s 상한·기존 물리·단독10m 계획을 보존했다. 공식 랩 인증이 아닌 격리 진단선 계측이다.")
section('Hungaroring 통합 결과',table([r for r in rows if r['track']=='hungaroring'])+'\n실제 원본 트랙의 격리 교통 구간 시험이다. 교통 포함 전체 랩 완주는 미실행이며 성공으로 주장하지 않는다.')
section('LiDAR 주파수','원본16×720/20Hz, IMU100Hz·encoder100Hz·camera30Hz 설정 및 위치/물리를 그대로 유지했다. 주행 구간 실제 header-stamp Hz는 scenario_matrix.json의 lidar_hz와 각 metrics.json active_sensor_hz에 있다. 시작 대기·정지 후 시간을 포함한 전체 hz_sim과 주행 Hz를 혼동하지 않는다. Wall 지연과 timeout은 별도 기록한다.')
section('연산 처리시간','각 실제 교통 상태 레코드에서 traffic_processing_ms 평균/p95/최대와 표본 수를 계산했다. 전체 callback 처리시간·sensor age도 별도 저장했다.20Hz는 센서 설정이며 모든 frame이50ms 이내 처리됐다는 의미가 아니다.50ms 초과·timeout이 있는 시험도 숨기지 않았다. scenario_matrix.json에는 각 시험의 실제 통계가 들어 있다.')
section('Gazebo RTF','world_stats의 RTF 평균/p05/최소와 sim_duration/wall_duration을 분리했다. 물리 timestep·시간 배율을 변경하지 않았다. 외부 부하와 actor 수에 따라wall 성능은 달라지므로 과거599.631초를 현재 코드의 실측값으로 재사용하지 않는다.')
section('CPU 및 메모리','시험의 Gazebo/참가자 자식 프로세스 합산 RSS(MiB), CPU(한 코어100% 기준)와 RTF를 저장했다. 독립 Python 관측자/GPU 메모리를 완전 포함한 시스템 총량이 아니다. 상대 actor 센서는 토픽 오염 및 부하 방지를 위해 시험 사본에서 제거했으므로12개 full sensor 팀 처리 성능을 입증하지 않는다.')
section('C++ 및 안전 시험',f"최종 ZIP의3개 CTest 실행 파일 전체 통과: {accept['cpp_three_executables_passed']}. 기존26개 시나리오+신규39개 고유 시나리오(68assertion, ID연결 반복 검사 포함). ROS14개 안전 회귀 통과: {accept['ros_safety14_passed']} ({sum(bool(v) for v in safety.values())}/{len(safety)}). 근거 final_release/ctest.log, ros_safety.json 및 timing.json. 개발 중 ctest23의 분리 점군 결합 거리 조건 실패도 보존했고 결합된 전체 bbox를 유지하는 범위에서 수정했다. H05의 ID분할은 전후 점군 union 병합으로 H06에서 개선됐으나 H06은 동적 점유 충돌로 포기했다. 매 프레임 차선 전환을 처음부터 계획하던 문제는 명령 진행량에 따라 남은 전환 구간을 줄이도록 보완했다. 개발 중 ctest20의 우측 선택 실패는4m 구간 밖 대상에 대한 좌우 동점 문제였고, 관측 대상과 끝점의 분리 여유를 비용에 추가하여 ctest21에서 수정했다. 경계/raw/동적 충돌 검사와 원본 제동 검사는 유지했다.")
section('최종 제출 ZIP 경로',f"`src/team_04/artifacts/stage5/final_release/team04_stage5.zip`\n\nSHA256 `{check.get('zip_sha256','미생성/미검사')}`. ZIP에는 소스/모델/설정/리소스와 시험 소스만 포함하고 원본 track/world/운영 코드/시험 로그/빌드 산출물은 포함하지 않는다. 이전 stage4 ZIP은 그대로다.")
section('청정 재빌드 결과',f"새 relocation_ws에 원본 공식 packer/intake로 해제, Jazzy colcon 재빌드, 공식 구조 validator와 소스/ZIP/해제본 바이트 일치 검사. 결과: {bool(check)}. 설치 리소스 검사: {check.get('installed_resources',False)}, 원본 물리/센서 해시 일치: {check.get('vehicle_and_sensor_sources_unchanged',False)}. 빌드 로그·공식 검사·fresh 안전 회귀는 final_release에 저장했다. 실제 주행의 run_config.json에는 사용 executable/model/plugin 해시가 있으므로 최종 설치본과 대조한다.")
section('공식 경기 규정 준수 여부','주행 입력은 자기 LiDAR·시작 Bool·clock과 자체 명령 이력이다. 상대 actor 정답 pose·센터라인·상대 제어는 독립 격리 시험에만 있다. 원본 race/track/world/중앙스폰/신호등/계측/물리 소스는 변경하지 않았다. 시험 전용 partition의 원본 공식 spawn/신호 절차를 재사용했다. 공식 경기 환경에서 상대 제어에 개입하지 않았다. 공식 주최 측 인증은 받지 않았다.')
section('미해결 문제',f"실제 엄격 추월 완료 시험: {passes or '없음'}. 충분한 관측과 간격 확보→추월→전체 후방 확인→복귀→5초 정상 주행을 모두 만족해야 한다. 전방 카메라가−1도·±4도 LiDAR 광선을 약0.186m에서 가리는 현상을 실측했다(front_shallow_ray_diagnosis.json). 정중앙의 낮은 상대차가 늦게 보일 수 있고 센서/물리 변경 금지 조건에서 모든 고속 교통 회피는 보장할 수 없다. 횡속도 편향과 가림 점유 때문에 보수적 정지/추월 포기가 남아 있다. 교통 전체 랩,12대 및 반복 내구 검증은 미실행. acceptance.json status={accept['status']}이며 전체 목표 달성을 선언하지 않는다.")
section('다음 단계 개선 사항','현재 물리 제약에서 LiDAR 반사면 변화에 강한 짧은 시간 창 속도 추정과 동적 후보 검증을 개선해야 한다. 실제 후방 관측·복귀까지 확인하는 좌우 추월 사례와 반복 시험이 우선이다. 미완료 과제를 progress.json에 저장했으며 기존 성공 기록은 재작성/재사용 성공 처리하지 않는다. 운영진이 물리/센서 변경을 허용하지 않는 한 전방 사각지대는 제한 조건으로 남는다.')
